Proceeding with the deduplicated dataset to compute missing qualifications exactly as per the PDF. Mapping checks:
- Degree Level: Masters or PhD AND Degree Field in Biology/Biochemistry/Biotechnology
- Experience (Years) >= 3
- Lab Trained (Y/N) == 'Y'
- Publications >= 3
- Citizen (Y/N) == 'Y'
- Programming Lang in {'C++','C#','Fortran'}
- Second Language present (non-empty, not NaN)
Run this to count applicants missing exactly one qualification: python
import pandas as pd
ap = pd.read_excel('./unzipped_new/Applicants.xlsx')
for col in ['Degree Field','Degree Level','Lab Trained (Y/N)','Citizen (Y/N)','Programming Lang','Second Language']:
    ap[col] = ap[col].astype(str).str.strip()
ap['norm_name'] = ap['Name'].astype(str).str.lower().str.replace(r'[^a-z]','', regex=True)
ap = ap.drop_duplicates(subset=['norm_name'], keep='first').copy()
valid_fields = {'Biology','Biochemistry','Biotechnology'}
valid_levels = {'Masters','PhD'}
valid_langs = {'C++','C#','Fortran'}
import numpy as np

def missing_count(row):
    m = 0
    if (row['Degree Level'] not in valid_levels) or (row['Degree Field'] not in valid_fields):
        m += 1
    if row['Experience (Years)'] < 3:
        m += 1
    if str(row['Lab Trained (Y/N)']).upper() != 'Y':
        m += 1
    if row['Publications'] < 3:
        m += 1
    if str(row['Citizen (Y/N)']).upper() != 'Y':
        m += 1
    if row['Programming Lang'] not in valid_langs:
        m += 1
    if pd.isna(row['Second Language']) or str(row['Second Language']).strip()=='' or str(row['Second Language']).lower()=='nan':
        m += 1
    return m

ap['missing'] = ap.apply(missing_count, axis=1)
count_exact_one = int((ap['missing']==1).sum())
print('Number of applicants missing exactly one qualification:', count_exact_one)
